rule detect_lateral_movement {
  meta:
    author = "Your Name"
  description = "Detects lateral movement via SMB to file server"
  reference = "https://example.com"
  tags = "lateral_movement smb"

  strings:
    $smb_path = "\\\\10.0.5.50\\\\share"{
      message = "Lateral movement via SMB to file server"
      id = 1
      classification = warning
    }

  condition:
    $smb_path{
      count >= 1
    }
}

